import json
from pathlib import Path
obj=json.loads(Path('benchmark/source_data.json').read_text())
# rating changes count by action
from collections import Counter, defaultdict
c=Counter([r['action'] for r in obj['sovereign_rating_changes']['data']])
print('actions',c)
# find downgrades per country with date
by=defaultdict(list)
for r in obj['sovereign_rating_changes']['data']:
    if r['action']=='downgrade':
        by[r['country']].append(r['date'])
print('downgrades per country')
for k in sorted(by):
    print(k, by[k])
# get 2024 debt and depreciation for scatter
latest={}
for r in obj['external_debt_to_gdp']['data']:
    if r['year']==2024:
        latest.setdefault(r['country'],{})['debt']=r['debt_gdp_pct']
for r in obj['currency_depreciation']['data']:
    if r['year']==2024:
        latest.setdefault(r['country'],{})['depr']=r['depreciation_pct']
print('2024 points')
for k,v in latest.items():
    print(k,v)
