p=Path('output/render.js')
p.write_text('''
const fs = require('fs');
const path = require('path');
const puppeteer = require('puppeteer');

(async () => {
  const inputHtml = path.resolve(__dirname, 'result.html');
  const outputPng = path.resolve(__dirname, '..', 'output', 'result.png');

  const browser = await puppeteer.launch({
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--font-render-hinting=medium']
  });

  const page = await browser.newPage();
  await page.setViewport({ width: 1400, height: 900, deviceScaleFactor: 2 });

  // Load local file.
  await page.goto('file://' + inputHtml, { waitUntil: 'networkidle0' });

  // Wait for chart canvas to have pixels.
  await page.waitForFunction(() => {
    const c = document.getElementById('mainChart');
    if (!c) return false;
    const ctx = c.getContext('2d');
    const px = ctx.getImageData(10, 10, 1, 1).data;
    return px[3] !== 0; // alpha not zero
  }, { timeout: 15000 });

  // Hide menu
  await page.addStyleTag({ content: '.viz-menu{display:none !important;}' });

  // Fit height to content
  const bodyHeight = await page.evaluate(() => {
    return Math.ceil(document.documentElement.scrollHeight);
  });
  await page.setViewport({ width: 1400, height: Math.min(Math.max(bodyHeight, 900), 2200), deviceScaleFactor: 2 });
  await page.waitForTimeout(250);

  const el = await page.$('body');
  await el.screenshot({ path: outputPng, type: 'png' });

  await browser.close();
})();
''')
print('wrote', p)
