from playwright.sync_api import sync_playwright
from pathlib import Path
html_path = Path('output/result.html').resolve()

with sync_playwright() as p:
    browser = p.chromium.launch()
    page = browser.new_page(viewport={"width": 1400, "height": 900, "deviceScaleFactor": 2})
    msgs=[]
    page.on('pageerror', lambda e: msgs.append(('pageerror', str(e))))
    page.on('console', lambda m: msgs.append((m.type, m.text)))
    page.goto('file://' + str(html_path), wait_until='load')
    page.wait_for_timeout(2500)
    # Check if canvas has pixels and chart exists
    res = page.evaluate("""() => {
      const c = document.getElementById('mainChart');
      const has = !!(c && c.chart);
      let alpha = null;
      if (c) {
        try {
          const d = c.getContext('2d').getImageData(10,10,1,1).data;
          alpha = d[3];
        } catch(e) { alpha = 'err'; }
      }
      return {has, alpha, w: c ? c.width : null, h: c ? c.height : null};
    }""")
    print('res', res)
    errs=[m for m in msgs if m[0] in ('pageerror','error')]
    print('errs', errs[:20])
    page.screenshot(path=str(Path('output/debug.png').resolve()), full_page=True)
    browser.close()
PY"}

