from pathlib import Path
from playwright.sync_api import sync_playwright
html_path = Path('output/result.html').resolve()
with sync_playwright() as p:
    browser=p.chromium.launch()
    page=browser.new_page(viewport={"width":1400,"height":900,"deviceScaleFactor":2})
    page.goto('file://' + str(html_path), wait_until='load')
    page.wait_for_timeout(2000)
    res = page.evaluate("""() => {
      const bodyBg = getComputedStyle(document.body).backgroundColor;
      const htmlBg = getComputedStyle(document.documentElement).backgroundColor;
      const bgVar = getComputedStyle(document.documentElement).getPropertyValue('--bg');
      const cardBg = getComputedStyle(document.querySelector('.card')).backgroundColor;
      const c = document.getElementById('mainChart');
      const cStyle = c ? getComputedStyle(c) : null;
      return {
        bodyBg, htmlBg, bgVar, cardBg,
        canvasDisplay: cStyle ? cStyle.display : null,
        canvasOpacity: cStyle ? cStyle.opacity : null,
        canvasBg: cStyle ? cStyle.backgroundColor : null,
      };
    }""")
    print(res)
    browser.close()
PY

