{"cmd":"python - <<'PY'
from playwright.sync_api import sync_playwright
from pathlib import Path
html_path = Path('output/result.html').resolve()
out_path = Path('output/result.png').resolve()

with sync_playwright() as p:
    browser = p.chromium.launch()
    page = browser.new_page(viewport={"width": 1400, "height": 900, "deviceScaleFactor": 2})
    page.goto('file://' + str(html_path), wait_until='load')
    # wait for canvas background to be painted
    page.wait_for_function("""() => {
      const c = document.getElementById('mainChart');
      if (!c) return false;
      const d = c.getContext('2d').getImageData(10,10,1,1).data;
      return d[3] === 255;
    }""", timeout=20000)

    page.add_style_tag(content='.viz-menu{display:none !important;}')
    page.wait_for_timeout(250)
    page.screenshot(path=str(out_path), full_page=True)
    browser.close()

print('wrote', out_path)
PY"}
